package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Tag;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.parser.TagFactory;
import org.jsoup.select.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_html_TriageGen0Test {

    private Element element;

    @Before
    public void setUp() {
        Tag tag = new Tag(Tag.valueOf("div"), Parser.htmlParser());
        element = new Element(tag, "", new org.jsoup.nodes.Attributes());
    }

    @Test
    public void testHtmlEmptyElement() {
        assertEquals("", element.html());
    }

    @Test
    public void testHtmlElementWithText() {
        element.appendText("Hello, World!");
        assertEquals("Hello, World!", element.html());
    }

    @Test
    public void testHtmlElementWithNestedElement() {
        Element child = element.appendElement("span");
        child.appendText("Nested");
        assertEquals("<span>Nested</span>", element.html());
    }

    @Test
    public void testHtmlElementWithAttributes() {
        element.attr("id", "test");
        element.appendText("With Attributes");
        assertEquals("<div id=\"test\">With Attributes</div>", element.html());
    }

    @Test
    public void testHtmlElementWithMultipleChildren() {
        Element child1 = element.appendElement("span");
        child1.appendText("Child 1");
        Element child2 = element.appendElement("span");
        child2.appendText("Child 2");
        assertEquals("<span>Child 1</span><span>Child 2</span>", element.html());
    }

    @Test
    public void testHtmlElementWithMixedContent() {
        element.appendText("Text ");
        Element child = element.appendElement("span");
        child.appendText("Mixed");
        element.appendText(" Content");
        assertEquals("Text <span>Mixed</span> Content", element.html());
    }

    @Test
    public void testHtmlElementWithEmptyChildren() {
        element.empty();
        assertEquals("", element.html());
    }

    @Test
    public void testHtmlElementWithNestedStructure() {
        Element child = element.appendElement("div");
        Element grandchild = child.appendElement("span");
        grandchild.appendText("Deeply Nested");
        assertEquals("<div><span>Deeply Nested</span></div>", element.html());
    }

    @Test
    public void testHtmlElementWithMultipleAttributes() {
        element.attr("id", "test").attr("class", "test-class");
        element.appendText("Multiple Attributes");
        assertEquals("<div id=\"test\" class=\"test-class\">Multiple Attributes</div>", element.html());
    }

    @Test
    public void testHtmlElementWithSelfClosingTags() {
        Element img = element.appendElement("img");
        img.attr("src", "image.jpg");
        assertEquals("<img src=\"image.jpg\"/>", element.html());
    }

    @Test
    public void testHtmlElementWithTextAndAttributes() {
        element.attr("class", "text-container");
        element.appendText("Text with Attributes");
        assertEquals("<div class=\"text-container\">Text with Attributes</div>", element.html());
    }

    @Test
    public void testHtmlElementWithEmptyAttributes() {
        element.attr("data-empty", "");
        assertEquals("<div data-empty=\"\"></div>", element.html());
    }

    @Test
    public void testHtmlElementWithComplexStructure() {
        Element child1 = element.appendElement("div");
        child1.appendText("Child 1");
        Element child2 = element.appendElement("span");
        child2.appendText("Child 2");
        Element child3 = element.appendElement("p");
        child3.appendText("Child 3");
        assertEquals("<div>Child 1</div><span>Child 2</span><p>Child 3</p>", element.html());
    }
}
